function validate([words]) {
  if (!Array.isArray(words) || words.length < 1 || words.length > 400) return 'words needs 1 to 400 strings.';
  const seen = new Set();
  for (const word of words) {
    if (typeof word !== 'string' || word.length < 2 || word.length > 400) return 'Each word has 2 to 400 letters.';
    if (!/^[a-z]+$/.test(word)) return 'Words use lowercase English letters only.';
    if (seen.has(word)) return 'All words must be distinct.';
    seen.add(word);
  }
  return null;
}

