function wordsAbbreviation(words) {
  const abbreviate = (word, keep) => {
    if (keep >= word.length - 2) return word;
    return word.slice(0, keep) + (word.length - 1 - keep) + word[word.length - 1];
  };
  const n = words.length;
  const prefix = new Array(n).fill(1);
  const result = words.map(word => abbreviate(word, 1));
  for (let i = 0; i < n; i++) {
    for (;;) {
      const clashes = [];
      for (let j = i + 1; j < n; j++) {
        if (result[j] === result[i]) clashes.push(j);
      }
      if (clashes.length === 0) break;
      clashes.push(i);
      for (const index of clashes) {
        prefix[index]++;
        result[index] = abbreviate(words[index], prefix[index]);
      }
    }
  }
  return result;
}

