function wordsAbbreviation(words) {
  // Follow the rules literally in rounds: every word whose abbreviation is shared grows its prefix together.
  const short = (w, k) => { const a = w.slice(0, k) + String(w.length - 1 - k) + w[w.length - 1]; return a.length < w.length ? a : w; };
  const keep = words.map(() => 1);
  for (;;) {
    const abbr = words.map((w, i) => short(w, keep[i]));
    const count = new Map();
    for (const a of abbr) count.set(a, (count.get(a) || 0) + 1);
    if (abbr.every(a => count.get(a) === 1)) return abbr;
    abbr.forEach((a, i) => { if (count.get(a) > 1) keep[i]++; });
  }
}

