function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const word = (length, alphabet) => Array.from({ length }, () => letters[Math.floor(rand() * alphabet)]).join('');
  const seen = new Set();
  const words = [];
  const add = (w) => { if (!seen.has(w)) { seen.add(w); words.push(w); } };
  if (size === 'small') {
    const alphabet = 2 + Math.floor(rand() * 3);
    const count = 1 + Math.floor(rand() * 8);
    for (let tries = 0; words.length < count && tries < 100; tries++) add(word(2 + Math.floor(rand() * 7), alphabet));
    return [words];
  }
  // Large: clusters of words with equal length, first and last letters, sharing prefixes of varied lengths.
  while (words.length < 400) {
    const length = 10 + Math.floor(rand() * 41);
    const base = word(length, 26);
    const members = 1 + Math.floor(rand() * 12);
    for (let m = 0; m < members && words.length < 400; m++) {
      const cut = 1 + Math.floor(rand() * (length - 2));
      add(base.slice(0, cut) + word(length - 1 - cut, 2 + Math.floor(rand() * 3)) + base[length - 1]);
    }
  }
  return [words];
}
